<?php require 'includes/database.php'; session_start();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$st=$pdo->prepare("INSERT INTO users(role,name,email,phone,password) VALUES('customer',?,?,?,?)");$st->execute([$_POST['name'],$_POST['email'],$_POST['phone'],password_hash($_POST['password'],PASSWORD_DEFAULT)]);header('Location: customer_success.php');exit;}catch(Throwable $e){$err='อีเมลนี้อาจถูกใช้งานแล้ว';}}require 'includes/header.php';?><main class="wrap"><form class="form card" method="post"><h2>สมัครลูกค้า</h2><?php if($err):?><p><?=$err?></p><?php endif;?><label>ชื่อ</label><input name="name" required><label>อีเมล</label><input type="email" name="email" required><label>เบอร์โทร</label><input name="phone"><label>รหัสผ่าน</label><input type="password" name="password" minlength="6" required><button class="btn">สมัครสมาชิก</button></form></main><?php require 'includes/footer.php';?>
